    /// <summary>
    /// Deflate crudo, sin cabecera zlib: los mismos bytes que descomprime el prototipo
    /// con DecompressionStream("deflate-raw"). Es el camino que ya sigue la trama de la
    /// ciudad, y por lo mismo — no meter una biblioteca en ninguno de los dos lados.
    /// </summary>
    static byte[] Inflar(string b64) {
        var bin = Convert.FromBase64String(b64);
        using (var ms = new MemoryStream(bin))
        using (var ds = new DeflateStream(ms, CompressionMode.Decompress))
        using (var salida = new MemoryStream()) {
            ds.CopyTo(salida);
            return salida.ToArray();
        }
    }

    static Dictionary<string, byte[]> _bases;

    /// <summary>
    /// Los bytes de cada silueta, sin repintar. Se descomprimen la primera vez que
    /// alguien pregunta y no al arrancar: son siete hojas de 24×32×8×16 y el juego
    /// arranca en la calle, donde a lo mejor no se cruza ni con la mitad.
    ///
    /// Una hoja con otras medidas se descarta en vez de reventar: el bloque lo escribe
    /// una herramienta que lee la celda del HTML, así que si no cuadra es que la forja
    /// ha cambiado y el arquetipo se forja, que es lo de siempre.
    /// </summary>
    public static Dictionary<string, byte[]> Bases {
        get {
            if (_bases != null) return _bases;
            _bases = new Dictionary<string, byte[]>();
            int esperado = ForjaChar.CW * ForjaChar.NDIRS * ForjaChar.CH * ForjaChar.NPOSES;
            foreach (var par in _hojas) {
                byte[] b;
                try { b = Inflar(string.Concat(par.Value)); }
                catch (Exception e) {
                    UnityEngine.Debug.LogWarning("no pude leer la silueta " + par.Key + ": " + e.Message);
                    continue;
                }
                if (b.Length != esperado) {
                    UnityEngine.Debug.LogWarning("silueta " + par.Key + " con medidas raras; se forja");
                    continue;
                }
                _bases[par.Key] = b;
            }
            return _bases;
        }
    }
}

